INSERT INTO animal (nome, foto_url, especie, porte, sexo, dt_nascimento, castrado, vacinas, vermifugado, condicao_especial, medicamento_continuo, historico_saude, microchipado, historia, motivo_doacao, personalidade, cidade, uf, situacao, id_responsavel) VALUES 
    ('Felix', '/fotos/felix.jpg', 'Cachorro', 'Médio', 'M', '2021-10-18', TRUE, 'Polivalente V10, Antirrábica', TRUE, FALSE, FALSE, 'Nunca ficou doente', TRUE, 'Felix era um cão bombeiro que auxiliava em operações de busca e salvamento, ajudando na busca com suas habilidades de faro e reduzindo o estresse em situações de pânico.', 'Após anos de serviço, ele está aposentado e busca um lar pra receber amor.', 'Felix é calmo, carinhoso, sua brincadeira favorita é cabo de guerra, e ele gosta de ficar próximo ao seu dono.', 'Três Lagoas', 'MS', 'Disponível', 1), 
    ('Jana', '/fotos/jana.jpg', 'Gato', 'Pequeno', 'F', '2025-10-18', TRUE, 'Tríplice felina, Antirrábica', TRUE, FALSE, FALSE, 'Nunca ficou doente', FALSE, 'Jana foi encontrada ainda filhote na porta de uma padaria e cresceu sendo cuidada pela ONG.', 'A ONG está com o abrigo lotado e quer garantir um lar definitivo para ela.', 'Jana é curiosa e brincalhona, adora perseguir bolinhas e dorme no colo.', 'Três Lagoas', 'MS', 'Disponível', 1), 
    ('Rai', '/fotos/rai.jpg', 'Cachorro', 'Grande', 'F', '2018-10-28', TRUE, 'Polivalente V10, Antirrábica', TRUE, TRUE, TRUE, 'Artrose leve diagnosticada aos 7 anos, controlada com medicação', TRUE, 'Rai viveu 6 anos com uma família que se mudou para o exterior e não pôde levá-la.', 'Os antigos tutores se mudaram de país e procuram uma casa tranquila para ela.', 'Rai é calma, obediente e adora passeios curtos. Convive bem com crianças e outros cães.', 'Três Lagoas', 'MS', 'Disponível', 1),
    ('Sam', '/fotos/sam.jpg', 'Cachorro', 'Grande', 'F', '2026-07-18', FALSE, 'V10 (1ª dose)', TRUE, FALSE, FALSE, 'Nunca ficou doente', FALSE, 'Sam nasceu de uma ninhada resgatada de um terreno baldio e foi criada em lar temporário.', 'Faz parte de uma ninhada resgatada e precisa de um lar definitivo.', 'Sam é agitada e muito sociável, adora morder brinquedos e aprende comandos rápido.', 'Três Lagoas', 'MS', 'Disponível', 1), 
    ('Joe', '/fotos/joe.jpg', 'Gato', 'Médio', 'M', '2017-10-18', TRUE, 'Tríplice felina, Antirrábica', TRUE, FALSE, FALSE, 'Faz acompanhamento anual, sem problemas de saúde', TRUE, 'Joe viveu com um senhor idoso por 8 anos, que faleceu no início do ano.', 'Perdeu o tutor e precisa de uma nova família que o acolha.', 'Joe é sossegado e carinhoso, gosta de tomar sol na janela e de ficar perto das pessoas.', 'Três Lagoas', 'MS', 'Disponível', 1), 
    ('Bela', '/fotos/bela.jpg', 'Gato', 'Pequeno', 'F', '2024-10-18', TRUE, 'Tríplice felina, Antirrábica', TRUE, FALSE, FALSE, 'Nunca ficou doente', TRUE, 'Bela foi resgatada de uma colônia de gatos de rua e passou por tratamento para se acostumar com pessoas.', 'Já está socializada e pronta para ir para uma casa de verdade.', 'Bela é tímida no começo, mas depois fica muito afetuosa. Adora brincar com varinhas de penas.', 'Três Lagoas', 'MS', 'Disponível', 1); 
